# ---------------------------------------------------------------- 2. แปลงขอบประเทศให้เป็นรูปที่ H3 รับ
def _ring(coords):
    out = []
    for c in coords:
        ll = (round(float(c[1]), 7), round(float(c[0]), 7))   # H3 รับ (lat, lng)
        if not out or out[-1] != ll:
            out.append(ll)
    if len(out) &gt; 1 and out[0] == out[-1]:
        out.pop()
    return out

HPS = []
for p in PARTS:
    loops = [_ring(p.exterior.coords)] + [_ring(i.coords) for i in p.interiors]
    loops = [l for l in loops if len(l) &gt;= 3]
    if loops:
        HPS.append(h3.LatLngPoly(loops[0], *loops[1:]))
MP = h3.LatLngMultiPoly(*HPS)

def fill(res):
    return np.array(sorted(h3.polygon_to_cells(MP, res)), dtype=object)

CELLS = {}
for r in RES_MEASURE:
    t1 = time.perf_counter()
    CELLS[r] = fill(r)
    log(f"เติม res {r}: {len(CELLS[r]):,} เซลล์ ({time.perf_counter()-t1:.2f} วิ)")

# กฎเจ็ดเท่า: H3 แบ่งแม่หนึ่งเซลล์เป็นลูกเจ็ดเซลล์ จำนวนเซลล์ต้องโตประมาณเจ็ดเท่าต่อขั้น
RATIO = {r: float(len(CELLS[r + 1]) / len(CELLS[r])) for r in RES_MEASURE[:-1]}
for r, v in RATIO.items():
    assert 6.0 &lt;= v &lt;= 7.3, f"res {r}→{r+1} อัตราส่วน {v:.2f} ไม่ใกล้ 7 = เติมไม่ครบหรือตกขอบ"
log("กฎเจ็ดเท่าผ่านการตรวจ: " + " · ".join(f"{r}→{r+1}={v:.2f}" for r, v in RATIO.items()))

3) Projection — Equidistant Conic ที่เส้นขนานโค้ง (ลุคแผ่นสำรวจยุคแรก)

# ---------------------------------------------------------------- 3. projection
CRS_P = CRS.from_proj4("+proj=eqdc +lat_0=14 +lon_0=101 +lat_1=8 +lat_2=20 "
                       "+x_0=0 +y_0=0 +units=m +no_defs +ellps=WGS84")
TRF = Transformer.from_crs(CRS.from_epsg(4326), CRS_P, always_xy=True)
def proj(lonlat):
    a = np.asarray(lonlat, float)
    x, y = TRF.transform(a[:, 0], a[:, 1])
    return np.column_stack([x, y])
def proj_geom(g):
    return shp_transform(lambda x, y, z=None: TRF.transform(x, y), g)
def rings_of(geom):
    polys = geom.geoms if geom.geom_type.startswith("Multi") else [geom]
    for p in polys:
        for ring in [p.exterior] + list(p.interiors):
            a = np.asarray(ring.coords, float)
            a = a[np.isfinite(a).all(axis=1)]
            if len(a) &gt; 3:
                yield a

thp = proj_geom(th)
X0, Y0, X1, Y1 = thp.bounds
PAD = 140_000
