&lt;/style&gt;&lt;/head&gt;&lt;body&gt;
&lt;div id="bar"&gt;
  &lt;h1&gt;Day 13 · Interactions&lt;/h1&gt;
  &lt;label class="ctl"&gt;&lt;span&gt;มืด = ไกลจุดทะเบียนไม่เกิน &lt;b id="dv"&gt;25&lt;/b&gt; กม.&lt;/span&gt;
    &lt;input id="dark" type="range" min="5" max="100" step="1" value="25"&gt;&lt;/label&gt;
  &lt;label class="ctl"&gt;&lt;span&gt;เงียบ = ไกลแหล่งเสียงอย่างน้อย &lt;b id="qv"&gt;10&lt;/b&gt; กม.&lt;/span&gt;
    &lt;input id="quiet" type="range" min="1" max="60" step="1" value="10"&gt;&lt;/label&gt;
  &lt;label class="ctl"&gt;&lt;span&gt;เน้นผู้ถือครอง&lt;/span&gt;
